const path=require("path"),fs=require("fs"),crypto=require("crypto"),Module=require("module"),SECURE_MAGIC="IMEF1",SECURE_HEADER_LEN=17,SECURE_OVERHEAD=33;function resolveSecureKey(){if(process.env.IM_SECURE==="0")return null;try{const r=require("./secure-key.js"),n=Buffer.from(r.m,"hex"),e=Buffer.from(r.k,"hex");if(n.length===32&&e.length===32){const t=Buffer.alloc(32);for(let c=0;c<32;c++)t[c]=n[c]^e[c];return t}}catch{}try{const n=fs.readFileSync(path.resolve(__dirname,"..","..","im-server","bin","config.yaml")).toString("utf8").match(/secure_file_key:\s*"([0-9a-fA-F]{64})"/);if(n)return Buffer.from(n[1],"hex")}catch{}return null}function decryptContainer(r,n){if(!r||r.length<=SECURE_OVERHEAD||r.subarray(0,5).toString("ascii")!==SECURE_MAGIC)throw new Error("主进程密文容器格式不符");const e=r.subarray(SECURE_HEADER_LEN),t=crypto.createDecipheriv("aes-256-gcm",n,r.subarray(5,SECURE_HEADER_LEN));return t.setAuthTag(e.subarray(e.length-16)),Buffer.concat([t.update(e.subarray(0,e.length-16)),t.final()])}const encKey=resolveSecureKey();if(encKey){const r=Module._resolveFilename;Module._resolveFilename=function(n,e,t,c){try{return r.call(this,n,e,t,c)}catch(o){if(o.code!=="MODULE_NOT_FOUND"||!/^\.\.?[\\/]/.test(n))throw o;const a=e?path.dirname(e.filename):__dirname,s=path.resolve(a,n),i=/\.enc$/i.test(s)?s:s+".enc";if(!fs.existsSync(i))throw o;return i}},Module._extensions[".enc"]=function(n,e){const t=decryptContainer(fs.readFileSync(e),encKey);n._compile(t.toString("utf8"),e)}}else fs.existsSync(path.join(__dirname,"main.js"))||(console.error("[loader] 加密密钥不可用且明文入口缺失（检查 IM_SECURE 环境变量与 secure-key.js），无法启动"),process.exit(1));require("./main.js");
